-- Educational activities. No clinical or therapeutic claims.
begin;
update public.recommendation_rules r set activity_id=a.id from public.wellness_activities a where r.activity_id is null and a.slug=case r.recommendation_type when 'EYE_COMFORT' then '20-20-20-visual-break' when 'POSTURE' then 'posture-reset' when 'SLEEP' then 'evening-wind-down' when 'DIGITAL_FATIGUE' then 'device-free-break' else '' end;
commit;
