insert into public.wellness_activities(id,title,slug,description,category,duration_seconds,instructions,benefits,safety_notes,icon,difficulty,is_active) values('40000000-0000-4000-8000-000000000001','20–20–20 visual break','20-20-20-visual-break','A short educational routine: 20–20–20 visual break. Follow the steps at a pace that feels comfortable.','EYE_COMFORT',20,'["Pause your screen task when it is safe to do so.","Look toward a comfortable point about 20 feet away for about 20 seconds.","Return to your screen when you feel ready."]'::jsonb,'["A planned opportunity to pause and reflect on your daily routine."]'::jsonb,'Stop if you feel pain, dizziness, or discomfort. Adapt this activity to your circumstances and mobility. This is general wellness education, not a treatment.','EYE_COMFORT', 'EASY',true) on conflict(slug) do nothing;
insert into public.wellness_activities(id,title,slug,description,category,duration_seconds,instructions,benefits,safety_notes,icon,difficulty,is_active) values('40000000-0000-4000-8000-000000000002','Visual rest break','visual-rest-break','A short educational routine: visual rest break. Follow the steps at a pace that feels comfortable.','EYE_COMFORT',30,'["Pause your current screen task.","Let your gaze rest away from the display without straining.","Return when comfortable."]'::jsonb,'["A planned opportunity to pause and reflect on your daily routine."]'::jsonb,'Stop if you feel pain, dizziness, or discomfort. Adapt this activity to your circumstances and mobility. This is general wellness education, not a treatment.','EYE_COMFORT', 'EASY',true) on conflict(slug) do nothing;
insert into public.wellness_activities(id,title,slug,description,category,duration_seconds,instructions,benefits,safety_notes,icon,difficulty,is_active) values('40000000-0000-4000-8000-000000000003','Screen ergonomics review','screen-ergonomics-review','A short educational routine: screen ergonomics review. Follow the steps at a pace that feels comfortable.','EYE_COMFORT',120,'["Notice whether glare or brightness feels uncomfortable.","Adjust your viewing position and display settings for comfort.","Review whether text is readable without leaning forward."]'::jsonb,'["A planned opportunity to pause and reflect on your daily routine."]'::jsonb,'Stop if you feel pain, dizziness, or discomfort. Adapt this activity to your circumstances and mobility. This is general wellness education, not a treatment.','EYE_COMFORT', 'EASY',true) on conflict(slug) do nothing;
